'use strict'

process.chdir(__dirname)

const cdpc = require('../index')

cdpc.runChilds([
  {
    name: 'date',
    command: 'date',
    restart: 'count',
    restartDelay: 1000,
    restartLimit: 10,
    options: {
      stdio: ['ignore', 1, 2]
    }
  },
  
  {
    name : 'app',
    file: 'app1.js',
    restart: 'always',
    restartDelay: 1000,
    options: {
      stdio: ['ignore', 1, 2]
    }
  }

])

console.log('15秒后暂停app (name=app)，并且在25秒后恢复服务...')

setTimeout(() => {
  console.log('app paused')
  cdpc.pause('app')
}, 15000)

setTimeout(() => {
  console.log('app resume')
  cdpc.resume('app')
}, 25000)

setTimeout(() => {
  console.log('测试完成，主进程退出。')
  process.exit(0)
}, 35000)
